          plus a non-blocking cold restart (mirrors MTP). Default-ON, so a
          null/absent on-disk value renders as on. */}
      {(() => {
        const cur = slot.model_id || slot.model || "";
        const m = (modelsQuery.data ?? []).map(normalizeApiModel).find(x => x.id === cur);
