                    setVision(!next);
                    setVisionErr(err?.message || "vision toggle failed");
                  } finally {
                    setVisionPending(false);
                  }
                }}
              />
              {visionErr && <div className="hint" style={{ color: "var(--err)" }}>{visionErr}</div>}
            </div>
          </div>
        );
      })()}
